/**
 * The webshop's WebMCP tools (#56, technical-plan.md §7.2): exactly the agent tools
 * that /mcp lists, with the same names, descriptions and input schemas, read from
 * agent-tools.json (generated by `uv run python -m app.interfaces.web_contract`).
 * Each tool calls its REST twin under /api/v1 with the session cookie.
 *
 * Agents get these tools and nothing else (technical-plan.md §9): confirm, cancel,
 * the inbox and page edits are never registered, and no result carries the
 * confirmation link. The page registers through `document.modelContext`, falling
 * back to `navigator.modelContext` (the API moved between the two in 2026).
 *
 * `installMcpB` first loads the MCP-B runtime (`@mcp-b/global`, #93): it wraps the
 * browser's own model context when there is one (ChatGPT's browser, Chrome with the
 * WebMCP flag) and installs a polyfill when there isn't, and it serves the tools to
 * the MCP-B extension through this tab, so an agent in ordinary Chrome can use them.
 */
import toolFile from '#lib/generated/agent-tools.json';

export interface AgentTool {
	name: string;
	description: string;
	inputSchema: Record<string, unknown>;
	rest: { method: 'GET' | 'POST'; path: string };
}

export const AGENT_TOOLS = toolFile as unknown as AgentTool[];

/** What a tool returns to the agent: MCP's CallToolResult shape. */
export interface ToolResult {
	content: { type: 'text'; text: string }[];
	structuredContent?: unknown;
	isError?: boolean;
}

export interface WebMcpTool {
	name: string;
	description: string;
	inputSchema: Record<string, unknown>;
	execute: (input: Record<string, unknown> | undefined) => Promise<ToolResult>;
}

/** The part of WebMCP's ModelContext we use. Implementations differ in how a tool is removed. */
export interface ModelContext {
	registerTool(tool: WebMcpTool, options?: { signal?: AbortSignal }): unknown;
	unregisterTool?(name: string): unknown;
}

const holder = (target: object) => (target as { modelContext?: ModelContext }).modelContext;

/**
 * Loads the MCP-B runtime once. Only this page's own origin may talk to it over the
 * tab transport (the extension's content script posts from the page itself), and it
 * never serves a parent frame. A failure leaves the browser's own context, if any.
 * A browser with only the older `navigator.modelContext` keeps it: MCP-B would put a
 * polyfill on `document` and the browser's own agent would never see the tools.
 */
export async function installMcpB(): Promise<void> {
	if (!holder(document) && holder(navigator)) return;
	try {
		window.__webModelContextOptions = { autoInitialize: false };
		const { initializeWebModelContext } = await import('@mcp-b/global');
		initializeWebModelContext({
			transport: { tabServer: { allowedOrigins: [window.location.origin] }, iframeServer: false }
		});
	} catch (error) {
		console.warn('WebMCP: could not load the MCP-B runtime', error);
	}
}

export function findModelContext(): ModelContext | null {
	return holder(document) ?? holder(navigator) ?? null;
}

export type TwinResponse = { ok: true; data: unknown } | { ok: false; status: number; detail: unknown };

/**
 * Calls a tool's REST twin. Path parameters fill the path; the other arguments go in
 * the query for GET (lists repeated) and in the JSON body for POST.
 */
export async function callTwin(
	tool: AgentTool,
	input: Record<string, unknown>,
	fetcher: typeof fetch = fetch
): Promise<TwinResponse> {
	const rest = { ...input };
	let missing: string | null = null;
	const path = tool.rest.path.replace(/\{(\w+)\}/g, (_, name: string) => {
		const value = rest[name];
		delete rest[name];
		if (value === undefined || value === null || value === '') missing = name;
		return encodeURIComponent(String(value));
	});
	if (missing) return { ok: false, status: 422, detail: `${missing} is required` };

	const init: RequestInit = { method: tool.rest.method, credentials: 'same-origin', headers: { accept: 'application/json' } };
	let url = path;
	if (tool.rest.method === 'GET') {
		const query = new URLSearchParams();
		for (const [name, value] of Object.entries(rest)) {
			for (const item of Array.isArray(value) ? value : [value]) {
				if (item !== undefined && item !== null) query.append(name, String(item));
			}
		}
		if (query.size) url += `?${query}`;
	} else if (Object.keys(rest).length) {
		init.headers = { accept: 'application/json', 'content-type': 'application/json' };
		init.body = JSON.stringify(rest);
	}

	let response: Response;
	try {
		response = await fetcher(url, init);
	} catch {
		return { ok: false, status: 0, detail: 'The shop could not reach the server.' };
	}
	const body = await response.json().catch(() => null);
	if (response.ok) return { ok: true, data: body };
	return { ok: false, status: response.status, detail: (body as { detail?: unknown } | null)?.detail ?? body };
}

const NOT_SIGNED_IN =
	'Not signed in. The person has to type their phone number on this page first; the tools then order for their demo account.';

function errorText(status: number, detail: unknown): string {
	if (status === 401) return NOT_SIGNED_IN;
	const text = typeof detail === 'string' ? detail : JSON.stringify(detail);
	return status ? `Error ${status}: ${text}` : text;
}

export function toolResult(response: TwinResponse): ToolResult {
	if (response.ok) {
		return { content: [{ type: 'text', text: JSON.stringify(response.data) }], structuredContent: response.data };
	}
	return { content: [{ type: 'text', text: errorText(response.status, response.detail) }], isError: true };
}

/**
 * Registers every agent tool. `onResult` sees each successful result, so the page can
 * show what the agent did. Returns a function that removes the tools again.
 */
export function registerAgentTools(
	context: ModelContext,
	onResult: (name: string, data: unknown) => void = () => {},
	fetcher: typeof fetch = (...args) => fetch(...args)
): () => void {
	const controller = new AbortController();
	const handles: unknown[] = [];
	for (const tool of AGENT_TOOLS) {
		const webTool: WebMcpTool = {
			name: tool.name,
			description: tool.description,
			inputSchema: tool.inputSchema,
			execute: async (input) => {
				const response = await callTwin(tool, input ?? {}, fetcher);
				if (response.ok) onResult(tool.name, response.data);
				return toolResult(response);
			}
		};
		const warn = (error: unknown) => console.warn(`WebMCP: could not register ${tool.name}`, error);
		try {
			handles.push(settle(context.registerTool(webTool, { signal: controller.signal }), warn));
		} catch (error) {
			warn(error);
		}
	}
	return () => {
		controller.abort();
		for (const handle of handles) {
			try {
				(handle as { unregister?: () => void } | undefined)?.unregister?.();
			} catch {
				// Already removed.
			}
		}
		for (const tool of AGENT_TOOLS) {
			try {
				settle(context.unregisterTool?.(tool.name));
			} catch {
				// Already removed, or removed through the signal.
			}
		}
	};
}

/** Implementations may answer with a promise: never leave its rejection unhandled. */
function settle(value: unknown, onError: (error: unknown) => void = () => {}): unknown {
	if (value instanceof Promise) value.catch(onError);
	return value;
}
